                        Log::info("订单 {$order['order_id']} 是平台订单且有在线支付金额，平台子订单可能存在");
                        return true;
                    }
                }
            }
        }

        Log::info("订单 {$order['order_id']} 未找到平台子订单记录，平台子订单不存在");
        return false;

    } catch (\Exception $e) {
        Log::error('检查平台子订单存在性失败: ' . $e->getMessage());
        // 出错时默认返回false，避免错误地尝试退款不存在的子订单
        return false;
    }
